theorem linear_over_sixth_eventually_small {A d ε : ℝ}
    (hA : 0 ≤ A) (hd : 0 < d) (hε : 0 < ε) :
    ∃ n₀ : ℕ, ∀ n : ℕ, n₀ ≤ n → 0 < n ∧ A*n/(d*n)^6 ≤ ε

theorem IsBernsteinFunction.affine {σ H : ℝ} {f : ℂ → ℂ}
    (hf : IsBernsteinFunction σ H f) (a b : ℝ) :
    IsBernsteinFunction (σ * |a|) H (bernsteinAffine f a b)

theorem IsBernsteinFunction.realification {σ H : ℝ} {f : ℂ → ℂ}
    (hf : IsBernsteinFunction σ H f) :
    IsBernsteinFunction σ H (bernsteinRealification f)

theorem IsBernsteinFunction.reflection {σ H : ℝ} {f : ℂ → ℂ}
    (hf : IsBernsteinFunction σ H f) :
    IsBernsteinFunction σ H (bernsteinReflection f)

theorem periodizationBandwidth_le {σ T : ℝ} {n : ℕ}
    (h : σ * T / (2 * Real.pi) ≤ (n : ℝ)) :
    periodizationBandwidth σ T ≤ n

theorem vallee_kills_high (L : ℕ) {f : CircleFunction}
    (hf : f∈spectrumSpace {j : ℤ | 2*L≤j.natAbs}) :
    ∀x,circleConvolution (valleeKernel L) f x=0

theorem exists_large_plateauPeriodError {α β H q : ℝ}
    (hα : 0 < α) (hβ : 0 ≤ β) (hβ1 : β < 1) (hH : 0 ≤ H) (hq : 0 < q) :
    ∃ R ≥ (1 : ℝ), ∀ r ≥ R, plateauPeriodError α (β*r) (2*r) H ≤ q

theorem periodic_real_bound_of_center {F : ℂ → ℂ} {T B : ℝ}
    (hT : 0 < T) (hp : Function.Periodic F (T : ℂ))
    (hb : ∀ x : ℝ, |x| ≤ T/2 → ‖F x‖ ≤ B) : ∀ x : ℝ, ‖F x‖ ≤ B

theorem plateauPeriodError_nonneg {α τ T H : ℝ}
    (hα : 0 ≤ α) (hτ : 0 ≤ τ) (hH : 0 ≤ H) :
    0 ≤ plateauPeriodError α τ T H

theorem normalized_indexed_mem_iff {r : ℝ} {k : ℕ} {t : Fin k → ℝ}
    {z : FourierCircle} :
    z ∈ normalizedNodes r (indexedRealNodes t) ↔ ∃ i, normalizeNode r (t i) = z

theorem finiteObstruction_of_centered_interval_real {H L : ℝ} {k : ℕ}
